function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[01]+$/.test(s)) return 's may contain only 0 and 1.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is an integer from 1 to s.length.';
  return null;
}

