function countDistinctStrings(s, k) {
  const n = s.length;
  if (n <= 12) {
    // Explore every reachable string directly.
    const seen = new Set([s]);
    const queue = [s];
    while (queue.length) {
      const cur = queue.pop();
      for (let start = 0; start + k <= n; start++) {
        let next = cur.slice(0, start);
        for (let j = start; j < start + k; j++) next += cur[j] === '0' ? '1' : '0';
        next += cur.slice(start + k);
        if (!seen.has(next)) { seen.add(next); queue.push(next); }
      }
    }
    return seen.size;
  }
  // Reachable strings are s XOR the span of the block masks over GF(2): 2^rank of them.
  const words = Math.ceil(n / 32);
  const basis = new Map();
  let rank = 0;
  for (let start = 0; start + k <= n; start++) {
    const row = new Uint32Array(words);
    for (let j = start; j < start + k; j++) row[j >> 5] |= 1 << (j & 31);
    for (;;) {
      let lead = -1;
      for (let w = 0; w < words && lead < 0; w++) if (row[w]) lead = w * 32 + (31 - Math.clz32(row[w] & -row[w]));
      if (lead < 0) break;
      if (!basis.has(lead)) { basis.set(lead, row); rank++; break; }
      const other = basis.get(lead);
      for (let w = 0; w < words; w++) row[w] ^= other[w];
    }
  }
  let count = 1;
  for (let r = 0; r < rank; r++) count = count * 2 % 1000000007;
  return count;
}

