function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 10);
  const k = 1 + Math.floor(rand() * n);
  const dense = rand();
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < dense ? '1' : '0';
  return [s, k];
}
